"""Authenticate the new compile-only carrier and independently recheck candidate DATA."""
import argparse,base64,json,os,subprocess,sys,time
from pathlib import Path
if __name__=='__main__':sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from scripts import panda_sdk_cg_build_policy as a
from scripts import panda_sdk_cg_carrier as carrier
from scripts import panda_sdk_cg_inputs as inputs
from scripts import panda_sdk_cg_static_gate as gate
from scripts import produce_panda_sdk_cg as host
from scripts import panda_sdk_image_archive as image_archive
from scripts import panda_sdk_link_image as image

def validate_receipt(r,files,source,activation,run_id,request_sha):
 required={'schema','status','source_sha','activation_sha','run_id','request_sha256','build_start_attempts','native_admitted','stage7_complete','target_execution','files','omissions'}
 optional={'scientific_native_runs','contract_sha256','image_sha256','staging','workflow_id','host_resources','compiler_build','failure','bundle_failure'}
 a.need(required<=set(r)<=required|optional,'closed production receipt fields')
 for k,v in dict(schema='panda-sdk-cg-production-v1',source_sha=source,activation_sha=activation,run_id=run_id,request_sha256=request_sha).items():a.need(r.get(k)==v,'production identity: '+k)
 a.need(r['native_admitted'] is False and r['stage7_complete'] is False and r['target_execution'] is False and type(r['build_start_attempts']) is int and r['build_start_attempts'] in (0,1),'compile-only flags/start bound');a.need(r.get('scientific_native_runs',0)==0 and type(r.get('scientific_native_runs',0)) is int,'scientific allowance remains zero')
 observed={k:v for k,v in files.items() if k!='reports/receipt.json'};a.need(r['files']==observed and type(r['omissions']) is list and r['omissions']==sorted(carrier.FILES-set(files)),'closed declared file manifest/omissions');a.need(r['status'] in ('BLOCKED','FAILED','CG_CANDIDATE_SELECTED_LAYOUT_MATCH_NOT_RUNTIME'),'known compile outcome')
 passed=r['status']=='CG_CANDIDATE_SELECTED_LAYOUT_MATCH_NOT_RUNTIME'
 if passed:a.need(set(files)==carrier.FILES and r['omissions']==[] and r['build_start_attempts']==1 and r.get('compiler_build',{}).get('status')=='CG_SDK_COMPILED_NOT_LOADED','complete actual success carrier')
 return dict(static_passed=passed,source_observer_default_off_observed=None,native_admitted=False,stage7_complete=False)

def accept_build(source,activation,run_id,out):
 a.need(a.hexstr(source,40) and a.hexstr(activation,40) and a.positive(run_id),'acceptance identity');out=Path(out).absolute();a.need(not out.exists(),'fresh independent acceptance output');out.mkdir(parents=True);result=dict(schema='panda-sdk-cg-accepted-v1',status='FAILED',actions_output_origin_authenticated=False,native_admitted=False,stage7_complete=False);a.write(out/'acceptance.json',result)
 try:
  token=subprocess.check_output(['gh','auth','token'],stderr=subprocess.PIPE,text=True,timeout=10).strip();client=host.BuildClient(out/'api',repository=a.REPO,token=token,deadline=time.monotonic()+1200,max_requests=96,max_payload_bytes=512*1024**2);meta=client.get_json('contents/'+a.REQUEST+'?ref='+activation,'request-content.json');a.need(meta['type']=='file' and meta['encoding']=='base64','request contents');raw=base64.b64decode(meta['content']);request=a.parse(raw);a.validate_request(request,a.ROOT);a.need(request['source_sha']==source,'accepted source');(out/'request.json').write_bytes(raw)
  ctx=dict(repository=a.REPO,head_sha=activation,run_id=run_id,attempt=1,event='push',actor=a.OWNER);run=host.authenticate_context(client,request,ctx,raw,completed=True);jobs=client.get_json('actions/runs/'+str(run_id)+'/jobs','build-jobs.json');a.need(jobs['total_count']==len(jobs['jobs'])==1,'unique build job');job=jobs['jobs'][0];a.need(job['name']=='build' and job['run_id']==run_id and job['head_sha']==activation and job['head_branch']==a.BRANCH and job['run_attempt']==1 and job['status']=='completed' and job['conclusion']==run['conclusion'],'exact build job');art=a.validate_artifact(run,client.get_json('actions/runs/'+str(run_id)+'/artifacts','artifacts.json'));client.download('https://api.github.com/repos/'+a.REPO+'/actions/artifacts/'+str(art['id'])+'/zip',out/'proof.zip',nbytes=art['size_in_bytes'],sha256=art['digest'][7:],kind='artifact');extracted=carrier.extract_carrier(out/'proof.zip',out/'candidate');receipt=a.parse(a.read(out/'candidate/reports/receipt.json',16*1024**2));semantics=validate_receipt(receipt,extracted['files'],source,activation,run_id,a.sha(raw));recomputed=None
  if semantics['static_passed']:
   c=inputs.contract();candidate=out/'candidate/candidate/libpandagl.so.data';obj=out/'candidate/candidate/layout-contract.o.data';image_tar=a.ROOT/'output/stage7-panda-sdk-abi0-image-01/acceptance/candidate/image.tar';check=image_archive.inspect_save_archive(image_tar,expected_tag='stage7-panda-sdk:actions-20261115-03',deadline=time.perf_counter()+180);a.need(check['image_tar_sha256']==c['current_image_sha256'] and check['config_digest']==c['current_config_digest'],'independent retained image');inventory=a.parse(a.read(a.ROOT/inputs.INVENTORY,16*1024**2));reader=image.SelectedImage(image_tar,image.Inventory(inventory),check,out/'provider-data',deadline=time.monotonic()+300);image.provider_graph(reader,a.read(candidate,4*1024**2));paths={p:Path(r['data_path']) for p,r in reader.cache.items()};recomputed=gate.audit_candidate(candidate,obj,receipt['compiler_build'],a.ROOT/c['audit_path'],paths);a.need(recomputed['status']=='CG_CANDIDATE_SELECTED_LAYOUT_MATCH_NOT_RUNTIME','independent static candidate gate failed');claimed=a.parse(a.read(out/'candidate/reports/gate.json',16*1024**2));a.need(all(claimed.get(k)==recomputed.get(k) for k in ['status','candidate_sha256','candidate_nbytes','offsets','layout','vtable_nbytes','native_admitted','full_object_abi_qualified','previous_abort_fixed','candidate_installed']),'reported/independent gate mismatch');configuration=a.parse(a.read(out/'candidate/reports/configuration.json',16*1024**2));a.need(configuration==receipt['compiler_build']['configuration'],'configuration/receipt binding');a.write(out/'independent-static-gate.json',recomputed)
  passed=semantics['static_passed'] and run['conclusion']=='success';result.update(status='AUTHENTICATED_CG_CANDIDATE_SELECTED_LAYOUT_MATCH_NOT_RUNTIME' if passed else 'AUTHENTICATED_CG_BUILD_FAILED',actions_output_origin_authenticated=True,static_passed=passed,claimed_static_passed=semantics['static_passed'],source_sha=source,activation_sha=activation,request_sha256=a.sha(raw),workflow_id=run['workflow_id'],run_id=run_id,run_attempt=1,job_id=job['id'],artifact_id=art['id'],artifact_zip_nbytes=art['size_in_bytes'],artifact_zip_sha256=art['digest'][7:],carrier=extracted,build_start_attempts=receipt['build_start_attempts'],build_slot_consumed=bool(receipt['build_start_attempts']),build_slot_remaining=0,source_observer_default_off_observed=None,target_execution=False,scientific_native_runs=0,full_object_abi_qualified=False,previous_abort_fixed=False,candidate_installed=False,strict_current_result='0/4 FAIL');a.write(out/'acceptance.json',result);return result
 except BaseException as e:result.update(status='FAILED',failure=type(e).__name__+': '+str(e));a.write(out/'acceptance.json',result);raise

def main():
 p=argparse.ArgumentParser();p.add_argument('--source',required=True);p.add_argument('--activation',required=True);p.add_argument('--run-id',type=int,required=True);p.add_argument('--out',required=True);args=p.parse_args()
 try:r=accept_build(args.source,args.activation,args.run_id,args.out);print(json.dumps({k:r[k] for k in ['status','static_passed','build_start_attempts','native_admitted']}));return 0
 except Exception as e:print('CG acceptance rejected: '+type(e).__name__+': '+str(e));return 2
if __name__=='__main__':raise SystemExit(main())
